import { useEffect, useRef, useState } from 'react';
import type { TenantUser } from '../../types';

interface Props {
  users: TenantUser[];
  saving: boolean;
  onCancel: () => void;
  onSave: (users: TenantUser[]) => void;
}

// Client-side convenience check only; the backend must re-validate.
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const MAX_EMAIL_LEN = 254;

/** Add/remove tenant users by email. The current user cannot remove themselves. */
export default function UsersModal({ users, saving, onCancel, onSave }: Props) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const [list, setList] = useState<TenantUser[]>(users);
  const [adding, setAdding] = useState(false);
  const [email, setEmail] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    const dialog = dialogRef.current;
    if (dialog && !dialog.open) dialog.showModal();
  }, []);

  const dirty = JSON.stringify(list) !== JSON.stringify(users);

  const addUser = () => {
    const value = email.trim().toLowerCase();
    if (value.length > MAX_EMAIL_LEN || !EMAIL_RE.test(value)) return setError('Enter a valid email address.');
    if (list.some((u) => u.email.toLowerCase() === value)) return setError('That user is already on this tenant.');
    setList([...list, { email: value }]);
    setEmail('');
    setError('');
    setAdding(false);
  };

  return (
    <dialog ref={dialogRef} className="ml-modal" aria-labelledby="users-title" onClose={onCancel}>
      <h2 id="users-title">Users</h2>
      <p className="admin__muted ml-modal__label">Email address</p>
      <ul className="user-list">
        {list.map((u) => (
          <li key={u.email} className="user-row">
            <span>
              {u.email}
              {u.isCurrentUser && <span className="you-tag">you</span>}
            </span>
            {!u.isCurrentUser && (
              <button
                type="button"
                className="icon-btn icon-btn--sm"
                aria-label={`Remove ${u.email}`}
                onClick={() => setList(list.filter((x) => x.email !== u.email))}
              >
                🗑
              </button>
            )}
          </li>
        ))}
      </ul>

      {adding ? (
        <form
          className="ml-form add-user"
          noValidate
          onSubmit={(e) => {
            e.preventDefault();
            addUser();
          }}
        >
          <label className="ml-field">
            <span>New user email</span>
            <input
              type="email"
              autoFocus
              autoComplete="off"
              maxLength={MAX_EMAIL_LEN}
              value={email}
              aria-invalid={!!error}
              aria-describedby={error ? 'add-user-error' : undefined}
              onChange={(e) => {
                setEmail(e.target.value);
                setError('');
              }}
            />
          </label>
          {error && (
            <p id="add-user-error" className="field-error" role="alert">
              {error}
            </p>
          )}
          <div className="ml-form__actions">
            <button type="button" className="btn btn--ghost" onClick={() => setAdding(false)}>
              Cancel
            </button>
            <button type="submit" className="btn btn--primary btn--purple">
              Add
            </button>
          </div>
        </form>
      ) : (
        <button type="button" className="link-btn" onClick={() => setAdding(true)}>
          <span aria-hidden="true">＋</span> Add user
        </button>
      )}

      <div className="ml-modal__actions">
        <button type="button" className="btn btn--ghost" onClick={() => dialogRef.current?.close()}>
          Cancel
        </button>
        <button type="button" className="btn btn--primary btn--purple" disabled={!dirty || saving} onClick={() => onSave(list)}>
          {saving ? 'Saving...' : 'Save'}
        </button>
      </div>
    </dialog>
  );
}
